
import type { ReturnShipmentLineItemAllocationInput } from './ReturnShipmentLineItemAllocationInput.js';

export type ShipmentInput = { /** Creation timestamp. Format: date-time. */ "created_at"?: never; /** RFC3339 timestamp. Format: date-time. */ "delivered_at"?: never; "direction"?: never; /** Caller-owned identifier for this resource in an external system. Caller-owned shipment identifier in external_system. Set with external_system to enable duplicate detection and replay for that provider reference. maxLength: 255. */ "external_reference_id"?: string; /** External carrier, aggregator, or fulfillment platform name for this shipment. Set with external_reference_id to enable duplicate detection and replay for that provider reference; without external_reference_id this is stored as provenance only. */ "external_system"?: string; "fulfillment_id"?: never; /** Carrier acceptance timestamp. For return shipments, this can satisfy an after_handoff execution gate for the declared return_line_items. Format: date-time. */ "handed_off_at"?: never; "metadata"?: Record<string, string>; "order"?: never; "order_id"?: never; /** Total number of packages attached to the shipment, including voided packages. Format: int32. minimum: 0. */ "package_count"?: never; "return_id"?: string; "return_line_items"?: Array<ReturnShipmentLineItemAllocationInput>; "shipment_id"?: never; /** RFC3339 timestamp. Format: date-time. */ "shipped_at"?: never; /** Read-only shipment state derived from the shipment's package states. An empty shipment remains a created draft. - `created`: The shipment leg exists but has not been packed or handed off. - `packed`: The shipment leg is packed and awaiting carrier handoff. - `shipped`: The shipment leg was handed to the carrier. - `in_transit`: The carrier is moving the shipment through its network. - `out_for_delivery`: The shipment is on its final delivery route. - `delivered`: The carrier reported successful delivery. - `delivery_attempted`: The carrier attempted delivery but did not complete it. Follow the carrier instructions before retrying delivery. - `exception`: A carrier exception is blocking normal progress. Resolve the carrier-reported issue. - `returned`: The shipment was returned toward or to its origin. - `voided`: The shipment was voided and will not continue through delivery. */ "status"?: never; /** Last update timestamp. Format: date-time. */ "updated_at"?: never; /** Monotonic shipment version for expected_version checks. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 1. */ "version"?: never; };
